(function(root,factory){const api=factory(root?.DirectorTimeline||(typeof require==='function'?require('./timeline-engine'):null));if(typeof module==='object'&&module.exports)module.exports=api;else root.DirectorAudioPost=api;})(typeof globalThis!=='undefined'?globalThis:this,function(TL){
  const DEFAULTS=Object.freeze({gainDb:0,pan:0,fadeIn:0,fadeOut:0,muted:false,normalize:false,dialogueEnhance:false});
  const clone=v=>JSON.parse(JSON.stringify(v));
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,Number(v)||0));
  function normalize(settings={}){return{gainDb:clamp(settings.gainDb??0,-60,24),pan:clamp(settings.pan??0,-1,1),fadeIn:clamp(settings.fadeIn??0,0,10),fadeOut:clamp(settings.fadeOut??0,0,10),muted:Boolean(settings.muted),normalize:Boolean(settings.normalize),dialogueEnhance:Boolean(settings.dialogueEnhance)}}
  function target(timeline,clipId){const found=TL.findClip(timeline,clipId);if(!found)return null;if(found.track.kind==='audio')return found;if(found.track.kind==='video'&&found.clip.linkedId){const linked=TL.findClip(timeline,found.clip.linkedId);if(linked?.track?.kind==='audio')return linked;}return null;}
  function get(timeline,clipId){const found=target(timeline,clipId);return found?normalize(found.clip.audio):normalize();}
  function set(timelineInput,clipId,property,value){const timeline=TL.normalizeTimeline(timelineInput),found=target(timeline,clipId);if(!found||found.track.locked||!(property in DEFAULTS))return timeline;const next=normalize(found.clip.audio);if(typeof DEFAULTS[property]==='boolean')next[property]=Boolean(value);else next[property]=normalize({...next,[property]:value})[property];found.clip.audio=next;return timeline;}
  function patch(timelineInput,clipId,values={}){let timeline=TL.normalizeTimeline(timelineInput);for(const [key,value] of Object.entries(values))timeline=set(timeline,clipId,key,value);return timeline;}
  function reset(timelineInput,clipId){const timeline=TL.normalizeTimeline(timelineInput),found=target(timeline,clipId);if(found&&!found.track.locked)found.clip.audio=clone(DEFAULTS);return timeline;}
  function linearGain(settings){const a=normalize(settings);return a.muted?0:Math.pow(10,a.gainDb/20)}
  function activeAudioTracks(timeline={}){const tracks=(timeline.tracks||[]).filter(t=>t.kind==='audio'&&!t.muted);const solo=tracks.filter(t=>t.solo);return solo.length?solo:tracks;}
  function exportFilters(clip={}){const a=normalize(clip.audio),duration=Math.max(.001,Number(clip.duration)||1),filters=[];if(a.dialogueEnhance)filters.push('highpass=f=80','lowpass=f=16000','acompressor=threshold=-18dB:ratio=3:attack=10:release=120:makeup=2');if(a.normalize)filters.push('loudnorm=I=-16:LRA=11:TP=-1.5');const gain=linearGain(a);if(Math.abs(gain-1)>1e-6)filters.push(`volume=${gain.toFixed(6)}`);if(Math.abs(a.pan)>1e-6){const l=clamp(1-a.pan,0,2),r=clamp(1+a.pan,0,2);filters.push('aformat=channel_layouts=stereo',`pan=stereo|c0=${l.toFixed(6)}*c0|c1=${r.toFixed(6)}*c1`);}if(a.fadeIn>1e-6)filters.push(`afade=t=in:st=0:d=${Math.min(a.fadeIn,duration).toFixed(6)}`);if(a.fadeOut>1e-6){const d=Math.min(a.fadeOut,duration);filters.push(`afade=t=out:st=${Math.max(0,duration-d).toFixed(6)}:d=${d.toFixed(6)}`);}return filters;}
  return{DEFAULTS,normalize,target,get,set,patch,reset,linearGain,activeAudioTracks,exportFilters};
});